fn main() {
    let dry_run = std::env::args().any(|a| a == "--dry-run");
    if !dry_run { sync::run(); }
}

pub const MAX_RETRIES: u32 = 5;

pub fn delay(attempt: u32) -> u64 {
    200 * 2u64.pow(attempt.min(MAX_RETRIES))
}

pub struct Config {
    pub remote: String,
}

pub fn run() {
    let db = std::fs::File::open("ferry.db").unwrap();
    fs2::FileExt::lock_exclusive(&db).ok();
}

